"""Generate ``docs/rules.md`` from rule metadata.

Run as ``python -m roschema.rules.gendocs`` (from the repo root) to regenerate
the rule reference. A test asserts the committed file stays in sync.
"""

from __future__ import annotations

import re
import sys
from pathlib import Path

from .. import __version__
from .breaking import ALL_BREAKING_RULES
from .lint import ALL_LINT_RULES
from .model import LintRule, Rule

_REPO_URL = "https://github.com/justagist/roschema"

_HEADER = (
    "# Rule reference\n\nGenerated by `python -m roschema.rules.gendocs`; do not edit by hand.\n"
)


def render_docs() -> str:
    """Render the full rule reference as Markdown."""
    parts = [_HEADER, _render_overview(), "\n## Breaking-change rules (`check`)\n"]
    for rule in ALL_BREAKING_RULES:
        parts.append(_render_breaking(rule))
    parts.append("\n## Lint rules (`lint`)\n")
    for lint_rule in ALL_LINT_RULES:
        parts.append(_render_lint(lint_rule))
    return "\n".join(parts).rstrip("\n") + "\n"


def find_rule(rule_id: str) -> Rule | LintRule | None:
    """The check or lint rule with ``rule_id`` (case-insensitive), if any."""
    rules: tuple[Rule | LintRule, ...] = (*ALL_BREAKING_RULES, *ALL_LINT_RULES)
    wanted = rule_id.upper()
    return next((rule for rule in rules if rule.id == wanted), None)


def docs_url(rule_id: str) -> str | None:
    """URL of a rule's section in ``docs/rules.md`` for the installed release.

    Links to the release tag so the text matches the rule that produced the
    finding; a development build links to ``main``.
    """
    rule = find_rule(rule_id)
    if rule is None:
        return None
    ref = "main" if "dev" in __version__ else f"v{__version__}"
    return f"{_REPO_URL}/blob/{ref}/docs/rules.md#{_anchor(rule)}"


def render_rule(rule: Rule | LintRule) -> str:
    """Render one rule's reference section as Markdown."""
    return _render_breaking(rule) if isinstance(rule, Rule) else _render_lint(rule)


def _render_overview() -> str:
    """One row per rule, linking to its section, for scanning what roschema reports."""
    lines = [
        "\n## Overview\n",
        "| Rule | Reports | Levels | Default |",
        "|---|---|---|---|",
    ]
    for rule in ALL_BREAKING_RULES:
        levels = ", ".join(rule.levels) or "n/a"
        lines.append(
            f"| [{rule.id}](#{_anchor(rule)}) | {rule.title} | {levels} | "
            f"{rule.default_severity.value} |"
        )
    for lint_rule in ALL_LINT_RULES:
        lines.append(
            f"| [{lint_rule.id}](#{_anchor(lint_rule)}) | {lint_rule.title} | lint | "
            f"{lint_rule.default_severity.value} |"
        )
    return "\n".join(lines) + "\n"


def _anchor(rule: Rule | LintRule) -> str:
    """GitHub's heading anchor for a rule's ``### ID -- Title`` section."""
    heading = f"{rule.id} -- {rule.title}".lower()
    return re.sub(r"[^\w\- ]", "", heading).replace(" ", "-")


def _render_breaking(rule: Rule) -> str:
    lines = [
        f"### {rule.id} -- {rule.title}",
        "",
        rule.description,
        "",
        f"- Levels: {', '.join(rule.levels) or 'n/a'}",
        f"- Default severity: {rule.default_severity.value}",
        "",
        f"*Rationale:* {rule.rationale}",
    ]
    if rule.example_before or rule.example_after:
        lines += [
            "",
            "```",
            f"# before\n{rule.example_before}",
            "# after",
            rule.example_after,
            "```",
        ]
    return "\n".join(lines) + "\n"


def _render_lint(rule: LintRule) -> str:
    lines = [
        f"### {rule.id} -- {rule.title}",
        "",
        rule.description,
        "",
        f"- Default severity: {rule.default_severity.value}",
        "",
        f"*Rationale:* {rule.rationale}",
    ]
    if rule.example_flagged or rule.example_preferred:
        lines += [
            "",
            "```",
            f"# flagged\n{rule.example_flagged}",
            "# preferred",
            rule.example_preferred,
            "```",
        ]
    return "\n".join(lines) + "\n"


_DOCS_PATH = Path("docs/rules.md")


def main(argv: list[str] | None = None) -> int:
    """CLI: no args writes the docs; ``--check`` verifies they are in sync."""
    argv = sys.argv[1:] if argv is None else argv
    rendered = render_docs()
    if not argv:
        _DOCS_PATH.parent.mkdir(parents=True, exist_ok=True)
        _DOCS_PATH.write_text(rendered, encoding="utf-8")
        print(f"wrote {_DOCS_PATH}")
        return 0
    if argv == ["--check"]:
        if _DOCS_PATH.is_file() and _DOCS_PATH.read_text(encoding="utf-8") == rendered:
            return 0
        print(
            "docs/rules.md is stale; regenerate with `python -m roschema.rules.gendocs`",
            file=sys.stderr,
        )
        return 1
    print("usage: python -m roschema.rules.gendocs [--check]", file=sys.stderr)
    return 2


if __name__ == "__main__":  # pragma: no cover
    raise SystemExit(main())
